def find_rc_v2(n):
    target = set(range(1, n**2 + 1))
    results = []
    import itertools
    # R = {r_0, r_1, ..., r_{n-1}} with 0 = r_0 < r_1 < ... < r_{n-1}
    # C = {c_0, c_1, ..., c_{n-1}} with 0 < c_0 < c_1 < ... < c_{n-1}
    # R+C = {1, ..., n^2}
    # c_0 = 1, r_{n-1} + c_{n-1} = n^2

    # We need to pick r_1, ..., r_{n-1} and c_1, ..., c_{n-2}
    # r_1, ..., r_{n-1} from {1, ..., n^2-1}
    # c_1, ..., c_{n-2} from {2, ..., n^2-2}

    # To optimize, r_{n-1} must be at least n-1 (since there are n-1 elements > 0)
    # and c_{n-1} must be at least n (since there are n-1 elements > 0)
    # So r_{n-1} <= n^2 - n.

    # Let's just try all r_1, ..., r_{n-1} and for each R, find all possible C.
    # This is still manageable for small n.
    for r_elements in itertools.combinations(range(1, n**2 - n + 1), n - 1):
        R = sorted(list(r_elements))
        R = [0] + R
        # R is now sorted. r_{n-1} = R[n-1]
        # c_0 = 1
        # c_{n-1} = n^2 - R[n-1]
        c_0 = 1
        c_last = n**2 - R[n-1]
        if c_last <= c_0: continue

        # Now we need to pick c_1, ..., c_{n-2} from {c_0+1, ..., c_last-1}
        # The number of such c_j is (c_last - c_0 - 1) choose (n-2)
        for c_middle in itertools.combinations(range(c_0 + 1, c_last), n - 2):
            C = sorted(list(c_middle))
            C = [c_0] + list(C) + [c_last]

            sumset = set()
            for r in R:
                for c in C:
                    sumset.add(r + c)
            if sumset == target:
                results.append((R, C))
    return results

